// Do not edit this file during the practice exercise.
// It reads every file in src/members/ and draws one button per file,
// so teammates only ever ADD their own file and never collide.

const files = import.meta.glob('./members/*.json', { eager: true, import: 'default' });

const members = Object.values(files).sort((a, b) => a.name.localeCompare(b.name));

// Pick dark or light text so every button stays readable on its own colour.
function textColorFor(hex) {
  const n = parseInt(hex.slice(1), 16);
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((c) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  });
  const luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return luminance > 0.4 ? '#14243B' : '#FFFFFF';
}

const wall = document.getElementById('wall');
const message = document.getElementById('message');
const count = document.getElementById('count');

count.textContent =
  members.length === 1 ? '1 teammate has added a button.' : `${members.length} teammates have added a button.`;

for (const m of members) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'member';
  button.style.background = m.color;
  button.style.color = textColorFor(m.color);
  button.textContent = `${m.emoji} ${m.name}`;
  button.addEventListener('click', () => {
    message.textContent = `${m.name}: “${m.message}”`;
  });
  wall.appendChild(button);
}
